    log(
      '[fah][sw] compaction pass ${pass.pass}: '
      '${pass.tokensBefore} → ${pass.tokensAfter} tokens '
      'engine=${pass.fallback ?? 'none'} ok=${pass.ok} '
      'hidden=${pass.hiddenRecords} '
